mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM CHALLENGE c
    WHERE c.CODE = #{code}
      AND c.DELETE_YN = 0
      AND c.PROGRESS_STATUS = 'ENDED'
      AND c.END_DATE <= #{now}
)

SELECT EXISTS (
    SELECT 1
    FROM CHALLENGE_RESULT r
    WHERE r.CHAL_CODE = #{code}
      AND r.STATUS = 'COMPLETED'
)
